android.extraBuildGradle:
dependencies {
  implementation 'com.android.billingclient:billing:9.1.0'
}

android {
  buildTypes {
    release {
      minifyEnabled true
      shrinkResources true
      proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'
    }
  }
}

afterbuild {
  doLast {
    def mappingFile = file('build/outputs/mapping/release/mapping.txt')
    def bundleDir = file('build/outputs/bundle/release')
    if (mappingFile.exists() && bundleDir.exists()) {
      copy {
        from mappingFile
        into bundleDir
        rename 'mapping.txt', 'mapping.txt'
      }
    }
  }
}

bundleRelease.finalizedBy afterbuild
